/**
 * The one thing to run.
 *
 * There were four audit tools before this and no obvious entry point, which is
 * precisely the gap the competing product's users describe about its six
 * agents. This is not a fifth report: it collects every finding the other
 * surfaces can produce -- waste detectors, cache attribution, routing -- ranks
 * them by measured cost per session, prices them, and hands back a queue where
 * each line names what to do about it.
 *
 * The specialised tools remain, for when you want the whole cache picture or
 * the full routing table. This is what you run when you do not know which of
 * them to run.
 */

import path from 'path';
import { fileURLToPath, pathToFileURL } from 'url';
import { dirname } from 'path';

const here = dirname(fileURLToPath(import.meta.url));

function coreUrl(name: string): string {
  return pathToFileURL(path.join(here, '..', '..', 'hooks-core', name)).href;
}

interface AuditModules {
  audit: any;
  waste: any;
  cache: any;
  routing: any;
  standing: any;
  wiki: any;
}

let cached: AuditModules | null = null;

async function modules(): Promise<AuditModules | null> {
  if (cached) return cached;
  try {
    const [audit, waste, cache, routing, standing, wiki] = await Promise.all([
      import(coreUrl('audit.mjs')),
      import(coreUrl('waste.mjs')),
      import(coreUrl('cache.mjs')),
      import(coreUrl('routing.mjs')),
      import(coreUrl('standing.mjs')),
      import(coreUrl('wiki.mjs')),
    ]);
    cached = { audit, waste, cache, routing, standing, wiki };
    return cached;
  } catch {
    return null;
  }
}

const say = (body: string, isError = false) => ({
  content: [{ type: 'text', text: body }],
  isError,
});

export async function tokenAudit(input: {
  full?: boolean;
  tier?: string;
  sessionsPerMonth?: number;
  decline?: string;
}): Promise<{
  content: Array<{ type: string; text: string }>;
  isError?: boolean;
}> {
  const mods = await modules();
  if (!mods)
    return say(
      'The audit is unavailable: the graph modules could not be loaded.',
      true
    );

  const cwd = process.cwd();
  const dir = mods.wiki.wikiDir(cwd);

  if (input?.decline) {
    mods.audit.decline(dir, input.decline);
    return say(
      `Noted. ${input.decline} will stop being suggested after ${mods.audit.DECLINE_LIMIT} declines.`
    );
  }

  let graph = null;
  try {
    graph = mods.wiki.load(dir);
  } catch {
    /* no graph costs the question-level detectors and nothing else */
  }

  const findings = [...mods.waste.detect(dir, graph)];

  // Cache invalidation is waste with a file and a line attached, so it belongs
  // in the same queue rather than in a report of its own.
  try {
    const transcript = mods.cache.transcriptFor(cwd);
    const health = mods.cache.cacheHealth(
      mods.cache.readCacheUsage(transcript)
    );
    for (const hit of mods.cache.attributeInvalidation(
      cwd,
      health?.prefixTokens ?? null
    )) {
      findings.push({
        id: 'cache-invalidation',
        title: `${hit.file}:${hit.line} has ${hit.why}, invalidating everything after it`,
        costPerSession: hit.costPerSession,
        file: hit.file,
        remedy: hit.remedy,
      });
    }

    // Routing is advice rather than a fix, and is listed as such.
    const table = mods.routing.outcomeTable(
      mods.routing.readEpisodes(transcript)
    );
    for (const shape of Object.keys(table)) {
      const decision = mods.routing.route(shape, table);
      if (decision.basis !== 'measured' || !decision.underpowered) continue;
      findings.push({
        id: 'model-routing',
        title:
          `${shape} is being run on ${decision.underpowered.tier}, which needed a retry in ` +
          `${Math.round(decision.underpowered.errorRate * 100)}% of episodes -- ${decision.recommend} costs less in expectation`,
        costPerSession: null,
        remedy: null,
      });
    }
  } catch {
    /* no transcript: the detector findings still stand on their own */
  }

  // Standing context -- skills, instructions and memory -- is waste charged
  // every session, so it belongs in the same queue rather than in a report of
  // its own. A stale claim is listed even without a transcript, because it is
  // provable from the code alone.
  //
  // The verdicts are also kept whole and handed to renderAudit, which renders
  // the panel. COMPUTED ONCE: flattening them into findings loses every file
  // that has nothing wrong with it, and loses the prefix total, so the panel
  // needs the verdicts themselves -- but it does not need them computed twice.
  let standing: unknown[] = [];
  try {
    const transcript = mods.cache.transcriptFor(cwd);
    standing = mods.standing.auditStanding(cwd, transcript);
    for (const verdict of standing as any[]) {
      for (const action of verdict.actions) {
        findings.push({
          id: `standing-${action.action}`,
          title: `${verdict.entry} (${verdict.tokens.toLocaleString()} tok/session): ${action.why}`,
          // A per-session prefix cost IS the cost, for trim and demote. A stale
          // claim costs correctness rather than tokens, so it carries no number
          // rather than a made-up one.
          costPerSession: action.action === 'fix' ? null : verdict.tokens,
          file: verdict.entry,
          remedy:
            action.kind === 'ours'
              ? {
                  kind: 'ours',
                  type: 'demote',
                  anchor: verdict.entry,
                  why: action.why,
                }
              : {
                  kind: 'yours',
                  type: 'edit',
                  file: verdict.entry,
                  why: action.why,
                  diff: action.diff,
                },
        });
      }
    }
  } catch {
    /* standing context is a bonus; never fail the audit over it */
  }

  const out = mods.audit.renderAudit(dir, findings, {
    full: Boolean(input?.full),
    tier: input?.tier || 'opus',
    sessionsPerMonth: input?.sessionsPerMonth || 60,
    standing,
  });

  // Recording that a finding was raised is what makes the before-and-after
  // measurable later; without it the trend has no point to split on.
  for (const item of findings) {
    try {
      mods.audit.raise(dir, item);
    } catch {
      /* never fail the audit over its own bookkeeping */
    }
  }

  return say(out.text);
}

export const AUDIT_TOOL = {
  name: 'token_audit',
  description:
    'The one thing to run. A single ranked queue of what is costing the most in this project -- waste detectors, prompt-cache ' +
    'invalidation attributed to a file and line, and model routing -- each priced per session and per month, each naming how to ' +
    'act on it. Reports what already-applied fixes actually saved, whether habits improved since the advice, and its own token ' +
    'cost; findings worth less than their printing cost are withheld unless full=true. Pass decline="<id>" to stop being told ' +
    'about something.',
  inputSchema: {
    type: 'object',
    properties: {
      full: {
        type: 'boolean',
        description:
          'Show every finding, including ones cheaper than printing them',
      },
      tier: {
        type: 'string',
        description:
          'Pricing tier for the dollar figures (haiku, sonnet, opus). Default opus',
      },
      sessionsPerMonth: {
        type: 'number',
        description: 'Assumption behind the monthly figures. Default 60',
      },
      decline: {
        type: 'string',
        description: 'A finding id you do not want raised again',
      },
    },
  },
} as const;


/**
 * The cache audit, exposed as a tool.
 *
 * Reports what the cache actually did, from the client's own transcript, and
 * attributes every invalidation it can to the file and line that caused it --
 * because a hit rate says the cache missed and cannot say why.
 *
 * Every number here is measured or absent. Where the transcript is unavailable
 * the constructs are still reported, without prices, rather than with invented
 * ones.
 */

import path from 'path';
import { fileURLToPath, pathToFileURL } from 'url';
import { dirname } from 'path';

const here = dirname(fileURLToPath(import.meta.url));

function coreUrl(name: string): string {
  return pathToFileURL(path.join(here, '..', '..', 'hooks-core', name)).href;
}

interface CacheModules {
  cache: any;
  keepwarm: any;
  wiki: any;
}

let cached: CacheModules | null = null;

async function modules(): Promise<CacheModules | null> {
  if (cached) return cached;
  try {
    const [cache, keepwarm, wiki] = await Promise.all([
      import(coreUrl('cache.mjs')),
      import(coreUrl('keepwarm.mjs')),
      import(coreUrl('wiki.mjs')),
    ]);
    cached = { cache, keepwarm, wiki };
    return cached;
  } catch {
    return null;
  }
}

const say = (body: string, isError = false) => ({
  content: [{ type: 'text', text: body }],
  isError,
});

export async function cacheAudit(): Promise<{
  content: Array<{ type: string; text: string }>;
  isError?: boolean;
}> {
  const mods = await modules();
  if (!mods)
    return say(
      'The cache audit is unavailable: the graph modules could not be loaded.',
      true
    );

  const cwd = process.cwd();
  const dir = mods.wiki.wikiDir(cwd);
  const lines: string[] = [];

  const turns = mods.cache.readCacheUsage(mods.cache.transcriptFor(cwd));
  const health = mods.cache.cacheHealth(turns);

  if (health) {
    lines.push('Measured, from the selected Claude Code transcript:');
    lines.push(
      `  Anthropic cache-read input .... ${health.read.toLocaleString()} tokens`
    );
    lines.push(
      `  Anthropic cache-write input ... ${health.written.toLocaleString()} tokens`
    );
    lines.push(
      `  hit rate ............ ${Math.round((health.hitRate || 0) * 100)}%`
    );
    lines.push(
      `  warm prefix ......... ${health.prefixTokens.toLocaleString()} tokens`
    );
    lines.push(
      `  read discount vs uncached ... ${health.inputCostEquivalentAvoidedVersusUncached.toLocaleString()} uncached-input cost-equivalent tokens`
    );
    lines.push(
      '  billing caveat ....... Anthropic-specific equivalent; excluded from universal savings and not an invoice'
    );

    const models = Object.keys(health.models);
    if (models.length > 1) {
      const cost = mods.cache.modelSwitchCost(turns);
      lines.push(
        `  ! ${models.length} models used in this session -- each switch re-writes the prefix ` +
          `(about ${cost.rewriteInputCostEquivalent.toLocaleString()} Anthropic uncached-input cost-equivalent tokens at its current size)`
      );
    }
  } else {
    lines.push(
      'No Anthropic cache measurements available: a Claude Code transcript could not be read.'
    );
    lines.push('The attribution below still applies, without prices.');
  }

  // Attribution: the half a hit rate cannot give.
  const blame = mods.cache.attributeInvalidation(
    cwd,
    health?.prefixTokens ?? null
  );
  if (blame.length) {
    lines.push('', 'Attributed cause:');
    for (const hit of blame.slice(0, 6)) {
      const price =
        hit.costPerSession != null
          ? `about ${hit.costPerSession.toLocaleString()} tokens re-written per session`
          : 'price unknown without a transcript measurement';
      lines.push(`  ! ${hit.file}:${hit.line} has ${hit.why} -- ${price}`);
      lines.push(`      ${hit.excerpt}`);
    }
    lines.push(
      '  These are your files, so they are proposed and never edited: remove the changing'
    );
    lines.push(
      '  value, or move that section to the end of the file so less sits behind it.'
    );
  } else {
    lines.push(
      '',
      'Attributed cause: nothing volatile found in the project instruction files.'
    );
  }

  // Keep-warm, decided rather than defaulted.
  const decision = mods.keepwarm.shouldKeepWarm(dir, {
    prefixTokens: health?.prefixTokens,
  });
  lines.push('', `Keep-warm: ${decision.action} -- ${decision.reason}`);

  const trip = mods.keepwarm.tripwire(dir);
  if (trip.tripped) lines.push(`  tripwire: ${trip.reason}`);
  else if (trip.observed > 0) {
    lines.push(`  ledger: ${trip.reason}`);
  }

  return say(lines.join('\n'));
}

export const CACHE_TOOL = {
  name: 'cache_audit',
  description:
    'Report Anthropic prompt-cache economics for this project: measured cache-read input, cache-write input, hit rate, and warm prefix size read from a Claude Code transcript, plus likely invalidation sources. Cost equivalents are labeled Anthropic-specific, excluded from universal savings, and are not invoices.',
  inputSchema: { type: 'object', properties: {} },
} as const;


#!/usr/bin/env node
/**
 * Token Optimizer MCP Daemon
 *
 * Long-running process that manages a persistent MCP server subprocess
 * and exposes it via named pipes (Windows) or Unix domain sockets (Linux/macOS)
 * for PowerShell hooks to communicate with.
 *
 * Performance: ~2-5ms per request (IPC overhead) vs ~1000-4000ms (npx spawn overhead)
 * Eliminates 285x slowdown caused by process spawning.
 *
 * Architecture:
 * - Daemon starts the MCP server (index.ts) as a child process via stdio
 * - Daemon listens on IPC socket (named pipe on Windows, Unix socket on Linux/macOS)
 * - PowerShell hooks connect via IPC and send JSON-RPC requests
 * - Daemon forwards requests to MCP server via stdin
 * - Daemon receives responses from MCP server via stdout
 * - Daemon returns responses to PowerShell hooks via IPC
 */

import net from 'net';
import os from 'os';
import path from 'path';
import fs from 'fs';
import { spawn, ChildProcess } from 'child_process';
import { fileURLToPath } from 'url';

const DAEMON_VERSION = '1.0.0';
const PLATFORM = os.platform();

// Get the directory of the current module
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Platform-specific socket paths
const SOCKET_PATH =
  PLATFORM === 'win32'
    ? '\\\\.\\pipe\\token-optimizer-daemon' // Windows named pipe
    : path.join(os.tmpdir(), 'token-optimizer-daemon.sock'); // Unix socket

// PID file for process management
const PID_FILE = path.join(
  process.env.USERPROFILE || process.env.HOME || os.homedir(),
  '.token-optimizer-daemon.pid'
);

/** The pid recorded in the pid file, or null when there is not a usable one. */
function recordedPid(): number | null {
  try {
    const pid = Number(fs.readFileSync(PID_FILE, 'utf8').trim());
    return Number.isInteger(pid) && pid > 0 ? pid : null;
  } catch {
    return null;
  }
}

/** Is that process actually there? Signal 0 tests without touching it. */
function isRunning(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

/**
 * Another daemon already owns this machine, if one is genuinely running.
 *
 * A pid file naming a process that no longer exists is stale -- left behind by
 * a hard kill, which on Windows is what SIGTERM does, so the handler never gets
 * to clean up. Stale files must not block a restart, which is why liveness is
 * checked rather than mere existence.
 */
function liveDaemonPid(): number | null {
  const pid = recordedPid();
  if (pid === null || pid === process.pid) return null;
  return isRunning(pid) ? pid : null;
}

/** Removes the pid file only when it still names this process. */
function releasePidFile(): void {
  try {
    if (recordedPid() === process.pid) fs.unlinkSync(PID_FILE);
  } catch {
    // A pid file we cannot read or remove is not worth failing shutdown over.
  }
}

interface DaemonStats {
  startTime: Date;
  requestCount: number;
  errorCount: number;
  avgResponseTime: number;
  mcpRestarts: number;
}

interface PendingRequest {
  id: string | number;
  resolve: (value: any) => void;
  reject: (error: Error) => void;
  timestamp: number;
}

const stats: DaemonStats = {
  startTime: new Date(),
  requestCount: 0,
  errorCount: 0,
  avgResponseTime: 0,
  mcpRestarts: 0,
};

// MCP server subprocess
let mcpProcess: ChildProcess | null = null;
const pendingRequests = new Map<string | number, PendingRequest>();
let requestIdCounter = 0;

/**
 * Start the MCP server as a child process
 */
function startMCPServer(): void {
  console.error('[DAEMON] Starting MCP server subprocess...');

  // Path to the MCP server index.js (built version)
  const serverPath = path.join(__dirname, 'index.js');

  if (!fs.existsSync(serverPath)) {
    console.error(`[DAEMON] ERROR: MCP server not found at ${serverPath}`);
    console.error('[DAEMON] Run "npm run build" first to compile TypeScript');
    process.exit(1);
  }

  // THE NODE THAT IS ALREADY RUNNING US, AND NO CONSOLE WINDOW.
  //
  // Resolving the bare string "node" walks PATH, so the daemon could hand the
  // server a different runtime than its own -- or fail outright when the host
  // launched us without Node on PATH. And with no windowsHide, Windows
  // allocates a console for the child whenever the daemon has none of its own,
  // which is every time it is started by a client rather than from a terminal:
  // a blank window per start, for the life of the daemon (#409).
  mcpProcess = spawn(process.execPath, [serverPath], {
    stdio: ['pipe', 'pipe', 'pipe'],
    env: process.env,
    windowsHide: true,
  });

  console.error(`[DAEMON] MCP server started (PID: ${mcpProcess.pid})`);

  // Handle stdout (responses from MCP server)
  let stdoutBuffer = '';
  mcpProcess.stdout?.on('data', (chunk) => {
    stdoutBuffer += chunk.toString();

    // Process complete JSON-RPC messages (newline-delimited)
    const lines = stdoutBuffer.split('\n');
    stdoutBuffer = lines.pop() || '';

    for (const line of lines) {
      if (line.trim()) {
        try {
          const response = JSON.parse(line);
          handleMCPResponse(response);
        } catch (error) {
          console.error('[DAEMON] Failed to parse MCP response:', error);
          console.error('[DAEMON] Invalid JSON:', line);
        }
      }
    }
  });

  // Handle stderr (logs from MCP server)
  mcpProcess.stderr?.on('data', (chunk) => {
    console.error('[DAEMON] MCP stderr:', chunk.toString().trim());
  });

  // Handle process exit
  mcpProcess.on('exit', (code, signal) => {
    console.error(
      `[DAEMON] MCP server exited (code: ${code}, signal: ${signal})`
    );

    // Reject all pending requests
    for (const [id, request] of pendingRequests.entries()) {
      request.reject(new Error('MCP server crashed'));
      pendingRequests.delete(id);
    }

    // Auto-restart if not intentional shutdown
    if (code !== 0 && !shuttingDown) {
      console.error('[DAEMON] Restarting MCP server in 1 second...');
      stats.mcpRestarts++;
      setTimeout(() => startMCPServer(), 1000);
    }
  });

  mcpProcess.on('error', (error) => {
    console.error('[DAEMON] MCP server error:', error);
  });
}

/**
 * Handle response from MCP server
 */
function handleMCPResponse(response: any): void {
  const id = response.id;

  if (!id) {
    console.error('[DAEMON] Received response without ID:', response);
    return;
  }

  const pending = pendingRequests.get(id);
  if (!pending) {
    console.error(`[DAEMON] No pending request for ID: ${id}`);
    return;
  }

  // Calculate response time
  const duration = Date.now() - pending.timestamp;
  stats.avgResponseTime =
    (stats.avgResponseTime * stats.requestCount + duration) /
    (stats.requestCount + 1);
  stats.requestCount++;

  console.error(`[DAEMON] Request ${id} completed in ${duration}ms`);

  // Resolve the pending request
  pending.resolve(response);
  pendingRequests.delete(id);
}

/**
 * Send request to MCP server and wait for response
 */
async function sendToMCPServer(request: any): Promise<any> {
  if (!mcpProcess || !mcpProcess.stdin) {
    throw new Error('MCP server not running');
  }

  // Generate unique request ID
  const id =
    request.id === undefined || request.id === null
      ? `daemon-${requestIdCounter++}`
      : request.id;
  request.id = id;

  console.error(`[DAEMON] Sending request ${id}: ${request.method}`);

  // Create promise for response
  const promise = new Promise((resolve, reject) => {
    pendingRequests.set(id, {
      id,
      resolve,
      reject,
      timestamp: Date.now(),
    });

    // Timeout after 30 seconds
    setTimeout(() => {
      if (pendingRequests.has(id)) {
        pendingRequests.delete(id);
        reject(new Error(`Request ${id} timed out after 30 seconds`));
      }
    }, 30000);
  });

  // Send request to MCP server
  mcpProcess.stdin.write(JSON.stringify(request) + '\n');

  return promise;
}

/**
 * Handle incoming request from PowerShell hook via IPC
 */
async function handleIPCRequest(data: string): Promise<string> {
  // Any request counts as activity — push back the idle self-exit.
  resetIdleTimer();
  const startTime = Date.now();

  let request: any;
  try {
    request = JSON.parse(data);

    console.error(`[DAEMON] IPC request: ${request.method}`);

    // Validate JSON-RPC 2.0 format
    if (request.jsonrpc !== '2.0' || !request.method) {
      return JSON.stringify({
        jsonrpc: '2.0',
        id: request.id || null,
        error: {
          code: -32600,
          message: 'Invalid Request: must be JSON-RPC 2.0 with method field',
        },
      });
    }

    // Handle daemon-specific methods
    if (request.method === 'daemon/stats') {
      const uptime = Date.now() - stats.startTime.getTime();
      return JSON.stringify({
        jsonrpc: '2.0',
        id: request.id,
        result: {
          version: DAEMON_VERSION,
          platform: PLATFORM,
          uptime,
          uptimeHuman: `${Math.floor(uptime / 1000)}s`,
          mcpServerPid: mcpProcess?.pid || null,
          ...stats,
        },
      });
    }

    if (request.method === 'daemon/shutdown') {
      console.error('[DAEMON] Shutdown requested via IPC');

      // Graceful shutdown
      shutdown();

      return JSON.stringify({
        jsonrpc: '2.0',
        id: request.id,
        result: { success: true, message: 'Daemon shutting down' },
      });
    }

    // Forward to MCP server
    const response = await sendToMCPServer(request);

    const duration = Date.now() - startTime;
    console.error(`[DAEMON] IPC request completed in ${duration}ms`);

    return JSON.stringify(response);
  } catch (error) {
    stats.errorCount++;
    console.error('[DAEMON] Error handling IPC request:', error);

    return JSON.stringify({
      jsonrpc: '2.0',
      id: request?.id ?? null,
      error: {
        code: -32603,
        message: error instanceof Error ? error.message : 'Internal error',
      },
    });
  }
}

let shuttingDown = false;

// Idle self-exit. Unlike the stdio MCP server, the daemon does NOT read stdin,
// so it can't use the stdin-close "parent is gone" signal — and on Windows a
// killed parent sends no signal. An orphaned daemon (plus its MCP child) would
// otherwise leak ~100 MB forever. So shut down after a stretch of no IPC
// requests; the next client transparently respawns the daemon. It's a singleton
// per socket, so at most one can exist, but this bounds even that one.
// Set TOKEN_OPTIMIZER_DAEMON_IDLE_MS=0 to disable (keep a persistent daemon).
const IDLE_TIMEOUT_MS = (() => {
  const raw = process.env.TOKEN_OPTIMIZER_DAEMON_IDLE_MS;
  if (raw === undefined || raw === '') return 30 * 60 * 1000; // default 30 min
  const n = Number(raw);
  return Number.isFinite(n) && n >= 0 ? n : 30 * 60 * 1000;
})();
let idleTimer: NodeJS.Timeout | null = null;

function resetIdleTimer(): void {
  if (IDLE_TIMEOUT_MS <= 0) return; // disabled: persistent daemon
  if (idleTimer) clearTimeout(idleTimer);
  idleTimer = setTimeout(() => {
    console.error(
      `[DAEMON] Idle for ${IDLE_TIMEOUT_MS}ms with no requests — self-terminating to avoid an orphaned daemon`
    );
    shutdown();
  }, IDLE_TIMEOUT_MS);
  // Intentionally NOT unref'd: we WANT this timer to fire and stop an idle daemon.
}

/**
 * Graceful shutdown
 */
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;

  console.error('[DAEMON] Shutting down gracefully...');

  if (idleTimer) {
    clearTimeout(idleTimer);
    idleTimer = null;
  }

  // Kill MCP server
  if (mcpProcess) {
    mcpProcess.kill('SIGTERM');
    mcpProcess = null;
  }

  // Remove the PID file ONLY IF IT IS OURS.
  //
  // It used to be removed unconditionally, and the path is shared by every
  // instance. So a second daemon that failed to bind the socket -- the normal
  // outcome of starting one twice -- ran this same shutdown path and deleted
  // the RUNNING daemon's pid file on its way out. The live daemon was then
  // untracked: nothing could find it to stop it, and the next start added
  // another orphan.
  releasePidFile();

  // Remove Unix socket
  if (PLATFORM !== 'win32' && fs.existsSync(SOCKET_PATH)) {
    fs.unlinkSync(SOCKET_PATH);
  }

  console.error('[DAEMON] Shutdown complete');
  process.exit(0);
}

/**
 * Start the daemon server
 */
function startDaemon(): void {
  console.error('[DAEMON] Token Optimizer MCP Daemon starting...');
  console.error(`[DAEMON] Version: ${DAEMON_VERSION}`);
  console.error(`[DAEMON] Platform: ${PLATFORM}`);
  console.error(`[DAEMON] Socket: ${SOCKET_PATH}`);

  // REFUSE BEFORE DOING ANY WORK, if a daemon is already up.
  //
  // Starting twice previously got as far as spawning a second MCP server child
  // before the socket bind failed, and the failure path then deleted the first
  // daemon's pid file. Checking first means the second invocation costs
  // nothing, says why, and leaves the running one strictly alone.
  const running = liveDaemonPid();
  if (running !== null) {
    console.error(
      `[DAEMON] Already running (PID ${running}) -- this instance is exiting.`
    );
    console.error(
      `[DAEMON] Stop it first if you meant to restart: kill ${running}`
    );
    process.exit(0);
  }

  // Start MCP server subprocess
  startMCPServer();

  // Remove stale socket file on Unix
  if (PLATFORM !== 'win32' && fs.existsSync(SOCKET_PATH)) {
    fs.unlinkSync(SOCKET_PATH);
  }

  // Create IPC server
  const server = net.createServer((socket) => {
    console.error('[DAEMON] Client connected');

    let buffer = '';

    socket.on('data', async (chunk) => {
      buffer += chunk.toString();

      // Process complete messages (newline-delimited)
      const messages = buffer.split('\n');
      buffer = messages.pop() || '';

      for (const message of messages) {
        if (message.trim()) {
          const response = await handleIPCRequest(message);
          socket.write(response + '\n');
        }
      }
    });

    socket.on('error', (err) => {
      console.error('[DAEMON] Socket error:', err);
    });

    socket.on('end', () => {
      console.error('[DAEMON] Client disconnected');
    });
  });

  server.listen(SOCKET_PATH, () => {
    console.error(`[DAEMON] Listening on ${SOCKET_PATH}`);
    console.error(`[DAEMON] PID: ${process.pid}`);

    // Claim the PID file. A stale one naming a dead process is replaced; a
    // live one is refused above, before we ever get here.
    fs.writeFileSync(PID_FILE, process.pid.toString());

    // Start the idle self-exit clock (no-op if disabled via env).
    resetIdleTimer();

    console.error('[DAEMON] Daemon ready');
  });

  server.on('error', (err) => {
    console.error('[DAEMON] Server error:', err);
    shutdown();
  });

  // Cleanup on exit
  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);
  process.on('exit', () => {
    if (mcpProcess) mcpProcess.kill();
  });
}

// Start daemon
startDaemon();


import path from 'path';
import os from 'os';
import fs from 'fs';
import { AnalyticsManager } from '../analytics/analytics-manager.js';
import { SqliteAnalyticsStorage } from '../analytics/analytics-storage.js';
import type { AnalyticsEntry } from '../analytics/analytics-types.js';
import {
  classifySavings,
  hasObservedReturnedContext,
  isVerifiedSavingsEntry,
  isVerifiedExpansionDebit,
  reportedSavings,
  verifiedTransportDelta,
  type SavingsClassification,
} from '../analytics/savings-classification.js';
import {
  MODEL_PRICE_CATALOG,
  priceTokenUsage,
} from '../analytics/provider-pricing.js';
import {
  readNativeProviderUsage,
  summarizeProviderUsage,
  type ProviderUsageSummary,
} from '../analytics/native-provider-usage.js';

let dashboardCache: {
  key: string;
  expiresAt: number;
  report: DashboardAnalyticsReport;
} | null = null;

interface EffectivePricing {
  available: boolean;
  effectiveInputUsdPerMillion: number | null;
  source: 'versioned-provider-model-catalog';
  verifiedAt: string;
  explanation: string;
}

export interface DashboardActionAnalytics {
  name: string;
  totalOperations: number;
  totalOriginalTokens: number;
  totalOptimizedTokens: number;
  totalTokensSaved: number;
  grossTokensSaved: number;
  expansionTokensReturned: number;
  unverifiedReportedTokensSaved: number;
  savingsPercentage: number | null;
  contextUsd: number | null;
  savedUsd: number | null;
  firstSeen: string;
  lastSeen: string;
  measuredSavingsOperations: number;
  pricedReturnedContextOperations: number;
  pricedSavingsOperations: number;
  verifiedExpansionOperations: number;
  unmeasuredSavingsOperations: number;
  observedReturnedContextOperations: number;
  unverifiedReportedOperations: number;
}

export interface DashboardAnalyticsReport {
  schemaVersion: 3;
  available: boolean;
  source: string;
  pricing: EffectivePricing;
  summary: {
    totalOperations: number;
    totalOriginalTokens: number;
    totalOptimizedTokens: number;
    measuredOptimizedTokens: number;
    totalTokensSaved: number;
    grossTokensSaved: number;
    expansionTokensReturned: number;
    unverifiedReportedTokensSaved: number;
    savingsPercentage: number | null;
    contextUsd: number | null;
    savedUsd: number | null;
    firstSeen: string | null;
    lastSeen: string | null;
    measuredSavingsOperations: number;
    pricedReturnedContextOperations: number;
    pricedSavingsOperations: number;
    verifiedExpansionOperations: number;
    unmeasuredSavingsOperations: number;
    actualReturnedContextOperations: number;
    legacyReportedContextOperations: number;
    observedReturnedContextOperations: number;
    unverifiedReportedOperations: number;
  };
  byAction: DashboardActionAnalytics[];
  byClient: Array<{
    name: string;
    attribution: 'recorded' | 'historical-unattributed';
    totalOperations: number;
    observedReturnedContextOperations: number;
    verifiedSavingsOperations: number;
    verifiedExpansionOperations: number;
    unverifiedReportedOperations: number;
    totalOptimizedTokens: number | null;
    totalTokensSaved: number | null;
    unverifiedReportedTokensSaved: number;
    contextUsd: number | null;
    savedUsd: number | null;
    pricedReturnedContextOperations: number;
    pricedSavingsOperations: number;
  }>;
  recent: Array<{
    name: string;
    originalTokens: number;
    optimizedTokens: number;
    tokensSaved: number;
    reportedTokensSaved: number;
    contextUsd: number | null;
    savedUsd: number | null;
    timestamp: string;
    savingsMeasured: boolean;
    classification: SavingsClassification;
    client: string | null;
    model: string | null;
  }>;
  measurement: {
    definition: string;
    tokenCountMethod: string;
    legacyPolicy: string;
    priceBasis: string;
  };
  providerUsage: ProviderUsageSummary;
}

function finite(value: unknown): number {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function pricing(): EffectivePricing {
  return {
    available: true,
    effectiveInputUsdPerMillion: null,
    source: 'versioned-provider-model-catalog',
    verifiedAt: MODEL_PRICE_CATALOG[0]?.verifiedAt || 'unknown',
    explanation:
      'API/list-price equivalents use the exact captured provider, model, request-time tier, uncached input, cache reads, cache writes, and output. Actual billed cost is shown only when the CLI reports it. Subscription and included-credit usage is never mislabeled as an invoice.',
  };
}

function inputEquivalent(entry: AnalyticsEntry, tokens: number): number | null {
  const direction = tokens < 0 ? -1 : 1;
  const metadata = entry.metadata || {};
  const priced = priceTokenUsage({
    client: entry.client || String(metadata.client || ''),
    provider: String(metadata.provider || ''),
    route: String(metadata.pricingRoute || metadata.route || ''),
    model: entry.model || String(metadata.model || ''),
    timestamp: entry.timestamp,
    usage: { uncachedInputTokens: Math.abs(tokens) },
  });
  return priced.available && priced.currency === 'USD' && priced.amount !== null
    ? priced.amount * direction
    : null;
}

function sumPriced(
  rows: AnalyticsEntry[],
  tokens: (entry: AnalyticsEntry) => number
): { amount: number | null; priced: number } {
  let amount = 0;
  let priced = 0;
  for (const row of rows) {
    const value = inputEquivalent(row, tokens(row));
    if (value === null) continue;
    amount += value;
    priced += 1;
  }
  return { amount: priced ? amount : null, priced };
}

/**
 * Summarize only provenance-qualified savings. Historical tool-reported rows
 * stay visible as an audit population, but never enter the verified headline.
 */
export function summarizeDashboardAnalytics(
  input: AnalyticsEntry[],
  options: { limit?: number; providerUsage?: ProviderUsageSummary } = {}
): DashboardAnalyticsReport {
  const limit = Math.min(100, Math.max(1, finite(options.limit) || 40));
  const price = pricing();
  const providerUsage = options.providerUsage || summarizeProviderUsage([]);
  const entries = input
    .filter(
      (entry) =>
        entry &&
        typeof entry.toolName === 'string' &&
        entry.toolName.trim() &&
        typeof entry.timestamp === 'string'
    )
    .map((entry) => ({
      ...entry,
      originalTokens: finite(entry.originalTokens),
      optimizedTokens: finite(entry.optimizedTokens),
      tokensSaved: finite(entry.tokensSaved),
    }))
    .sort((a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp));

  const groups = new Map<string, AnalyticsEntry[]>();
  for (const entry of entries) {
    const name = entry.toolName.trim();
    const group = groups.get(name) || [];
    group.push(entry);
    groups.set(name, group);
  }

  const byAction = [...groups.entries()]
    .map(([name, rows]): DashboardActionAnalytics => {
      const verifiedRows = rows.filter(isVerifiedSavingsEntry);
      const expansionRows = rows.filter(isVerifiedExpansionDebit);
      const observedRows = rows.filter(hasObservedReturnedContext);
      const unverifiedRows = rows.filter(
        (row) =>
          !isVerifiedSavingsEntry(row) &&
          !isVerifiedExpansionDebit(row) &&
          reportedSavings(row) > 0
      );
      const totalOriginalTokens = verifiedRows.reduce(
        (sum, row) => sum + row.originalTokens,
        0
      );
      const totalOptimizedTokens = observedRows.reduce(
        (sum, row) => sum + row.optimizedTokens,
        0
      );
      const grossTokensSaved = verifiedRows.reduce(
        (sum, row) => sum + reportedSavings(row),
        0
      );
      const expansionTokensReturned = expansionRows.reduce(
        (sum, row) => sum + row.optimizedTokens,
        0
      );
      const totalTokensSaved = grossTokensSaved - expansionTokensReturned;
      const unverifiedReportedTokensSaved = unverifiedRows.reduce(
        (sum, row) => sum + reportedSavings(row),
        0
      );
      const timestamps = rows.map((row) => row.timestamp).sort();
      const returnedCost = sumPriced(
        observedRows,
        (row) => row.optimizedTokens
      );
      const savedCost = sumPriced([...verifiedRows, ...expansionRows], (row) =>
        verifiedTransportDelta(row)
      );
      return {
        name,
        totalOperations: rows.length,
        totalOriginalTokens,
        totalOptimizedTokens,
        totalTokensSaved,
